script:
button { cursor: pointer; }
button:disabled { opacity: 0.45; cursor: not-allowed; }
a, button { transition: opacity 0.15s ease, background 0.15s ease, color 0.15s ease; }
a:hover { opacity: 0.7; }
:focus-visible { outline: 2px solid var(--110f8853-a230-4200-88a6-a86935e82cca, #8A5A3B); outline-offset: 2px; }
[data-shop="variant-option"][data-selected="true"] {
	background: var(--a485e9e8-6de2-4f17-8588-a50aaf8be886, #201D19);
	color: var(--51c524f3-1a60-4ab6-96a0-f310e33650b7, #FAF9F7);
	border-color: var(--a485e9e8-6de2-4f17-8588-a50aaf8be886, #201D19);
}
[data-shop="cart-count"][data-empty="true"] { display: none; }
input, textarea { font-family: inherit; }
